{
  lix,
  top,
  path,
  ...
}: let
  inherit (lix.attrsets) asAttrsIf attrByPath hasAttrByPath setAttrByPath;
  inherit (lix.modules) mkProgramToggle;
  inherit (lix.options) mkEnableOption;
  inherit (lix.lists) elem;
  inherit (lix.types) isList isString;
in
  mkProgramToggle {
    inherit top path;
    extraOptions = mod: let
      inherit (mod) config get;
      name = get.names.name;
    in {
      isRequired =
        mkEnableOption "Whether ${name} is selected by the host or user"
        // {
          default = let
            target = config.parent.selected or null;
          in
            if isList target
            then elem name target
            else if isString target
            then target == name
            else false;
        };
      needsNiri =
        mkEnableOption "Whether ${name} requires Niri integration"
        // {default = config.domain.backends.niri.enable or false;};
    };
    extraHomeConfig = mod: let
      inherit (mod) config cfg get options;
      entryPath = get.names.entry.path;
      target = entryPath ++ ["niri"];
      targetExists = hasAttrByPath target options;
      includesEnable =
        if targetExists
        then attrByPath (entryPath ++ ["niri" "includes" "enable"]) true config
        else true;
    in
      asAttrsIf targetExists (
        setAttrByPath target {
          enableKeybinds = (cfg.needsNiri or false) && !includesEnable;
          enableSpawn = cfg.needsNiri or false;
        }
      );
  }

{
  lix,
  top,
  host,
  ...
} @ args: let
  inherit (lix.modules) mkModules;
  moduleArgs = {
    inherit extraArgs;
    base = ./.;
    excludes = [
      "alacritty"
      "claude"
      "codex"
      "delta"
      "foot"
      "gh"
      "git"
      "gitui"
      "hermes"
      "jj"
      "kitty"
      "mango"
      "niri"
      "ollama"
      "openclaw"
      "starship"
      "tailscale"
      "vicinae"
      "zen-browser"
    ];
  };
  extraArgs = {
  };
  inner = mkModules (args // moduleArgs);
in {
  core.imports = inner.imports or [];
  home.imports = inner.home-manager.sharedModules or [];
}

{
  lib,
  registry,
  mkArgs,
  ...
}: let
  name = "delta";
  pkgName = registry.${name}.package;
  inherit (lib.modules) mkDefault mkIf;
in {
  core = {
    config,
    pkgs,
    ...
  }: let
    scope = "core";
    inherit (mkArgs {inherit config scope;}) cfg;
  in {
    config = mkIf cfg.enable {
      environment.systemPackages = [pkgs.${pkgName}];
    };
  };
  home = {
    config,
    pkgs,
    ...
  }: let
    scope = "home";
    inherit (mkArgs {inherit config scope;}) cfg opt mkEnableMod;
  in {
    options = opt {${name}.enable = (mkEnableMod {inherit name;}).true;};
    config = mkIf cfg.enable {
      programs.${name} = {
        enable = mkDefault true;
        package = mkDefault pkgs.${pkgName};
        enableGitIntegration = mkDefault true;
        options = {
          navigate = mkDefault true;
          side-by-side = mkDefault true;
        };
      };
    };
  };
}

{
  lix,
  top,
  lib,
  dom,
  mod,
  ...
}: let
  inherit (lib.modules) mkIf;
  inherit (lix.options) mkModuleArgs;
  mk = scope: {
    config,
    pkgs,
    ...
  }: let
    module = mkModuleArgs {inherit config top dom mod scope pkgs;};
    opt = module.set.options.module;
    package = module.get.package;
    enable = module.get.config.module.enable or false;
  in {
    options = opt {enable = module.set.enable {default = config.${top}.interface.protocol.wayland;};};
    config = mkIf enable (
      if scope == "core"
      then {environment.systemPackages = [package];}
      else {programs.${mod} = {inherit enable package;};}
    );
  };
in {
  core = mk "core";
  home = mk "home";
}

