  home = {config, ...}: let
    scope = "home";
    inherit (mkArgs {inherit config scope;}) opt;
  in {
    options = opt {
      profile.settings = mkOption {
        type = attrs;
        default = {
          "zen.workspaces.continue-where-left-off" = true;
          "zen.view.compact.hide-tabbar" = true;
          "zen.urlbar.behavior" = "float";
          "zen.welcome-screen.seen" = true;
        };
        description = "about:config preferences written to prefs.js for the configured profile.";
      };
      profile.mods = mkOption {
        type = listOf str;
        default = [
          "e122b5d9-d385-4bf8-9971-e137809097d0"
          "253a3a74-0cc4-47b7-8b82-996a64f030d5"
          "4ab93b88-151c-451b-a1b7-a1e0e28fa7f8"
