{
  lix,
  top,
  host,
  config,
  ...
}: let
  inherit (lix.attrsets) removeEmpty;
  inherit (lix.options) mkOption;
  inherit (lix.types) str nullOr float enum;
  mod = "localization";
  src = host.${mod} or {};
  #? One options declaration, reused for both `core` and `home`
  options.${top}.${mod} = {
    #? Schema S3
    latitude = mkOption {
      type = nullOr float;
      default = src.latitude or null;
      description = "Decimal degrees, -90 to 90. Negative = South.";
    };
    longitude = mkOption {
      type = nullOr float;
      default = src.longitude or null;
      description = "Decimal degrees, -180 to 180. Negative = West.";
    };
    city = mkOption {
      type = nullOr str;
      default = src.city or null;
      description = "Human-readable location string, for display only.";
    };
    locator = mkOption {
      type = enum ["geoclue2" "manual" "networkmanager"];
      default = src.locator or "geoclue2";
      description = "Location provider backend.";
    };
    #? Required per schema S3. No default supplied here when the
    timeZone = mkOption (
      {
        type = str;
        description = "tzdata identifier, e.g. \"America/Jamaica\".";
      }
      // (
        if (src.timeZone or null) != null
        then {default = src.timeZone;}
        else {}
      )
    );
    defaultLocale = mkOption (
      {
        type = str;
        description = "glibc locale string, e.g. \"en_US.UTF-8\".";
      }
      // (
        if (src.defaultLocale or null) != null
        then {default = src.defaultLocale;}
        else {}
      )
    );
  };
  #? `core` (NixOS) sets geoclue location, the system timezone, and
  mk = scope: {
    inherit options;
    config = let
      #? Read back the RESOLVED option values for *this scope's own*
      cfg = config.${top}.${mod};
    in
      if scope == "core"
      then {
        location = removeEmpty {
          inherit (cfg) latitude longitude;
          provider = cfg.locator;
        };
        time.timeZone = cfg.timeZone;
        i18n.defaultLocale = cfg.defaultLocale;
      }
      else {
        home.language.base = cfg.defaultLocale;
      };
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  top,
  paths,
  ...
}: let
  inherit (lix.attrsets) filterAttrs mapAttrs mapAttrs';
  inherit (lix.environment) mkVariables mkCdAliases;
  inherit (lix.lists) elem;
  inherit (lix.options) mkOption;
  inherit (lix.types) attrsOf anything;
  paths' = {
    local = paths.local or {};
    store = paths.store or {};
  };
  keys = {
    core = [
      "api"
      "configuration"
      "dbg"
      "documentation"
      "libraries"
      "secrets"
      "shells"
      "src"
      "templates"
      "utilities"
    ];
    home = [
      "documents"
      "downloads"
      "music"
      "pictures"
      "projects"
      "videos"
    ];
  };
  pick = scope: local: filterAttrs (name: _: elem name keys.${scope}) local;
  mkGroup = attrs: {
    variables = mkVariables {
      inherit attrs;
      prefix = top;
    };
    aliases = mkCdAliases attrs;
  };
  mk = scope: {config, ...}: let
    cfg = config.${top}.paths or {};
    group = mkGroup (
      if scope == "core"
      then let
        local = pick "core" paths'.local;
        store =
          mapAttrs' (name: value: {
            name = "${name}_store";
            inherit value;
          })
          (pick "core" paths'.store);
      in
        local // store
      else pick "home" (cfg.local or paths'.local)
    );
  in {
    options.${top}.paths = mkOption {
      type = attrsOf anything;
      default = {};
      description = "Staged path data for dots: raw local/store maps, core.{variables,aliases}, and a per-user home.<user>.{variables,aliases} breakdown -- the single source injected into environment/home options.";
    };
    config =
      {
        ${top}.paths =
          {inherit (paths') local store;}
          // (
            if scope == "core"
            then {
              core = group;
              home = mapAttrs (
                _: userCfg: userCfg.${top}.paths.home or {}
              ) (config.home-manager.users or {});
            }
            else {home = group;}
          );
      }
      // (
        if scope == "core"
        then {
          environment = {
            inherit (group) variables;
            shellAliases = group.aliases;
          };
        }
        else {
          home = {
            sessionVariables = group.variables;
            shellAliases = group.aliases;
          };
        }
      );
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  top,
  host,
  config,
  ...
}: let
  inherit (lix.attrsets) optionalAttrs;
  inherit (lix.modules) mkDefault;
  inherit (lix.lists) elem;
  inherit (lix.options) mkOption mkEnableOption;
  inherit (lix.types) str nullOr listOf attrsOf enum int float submodule;
  #? Raw host data is consulted ONLY as option defaults below. Nothing
  interfaceSrc = host.interface or {};
  devicesSrc = host.devices or {};
  specsSrc = host.specs or {};
  #? Schema S8: devices.file mounts.
  fsEntrySubmodule = submodule {
    options = {
      device = mkOption {
        type = str;
        description = "Source block device, addressed by UUID or path.";
      };
      fsType = mkOption {
        type = nullOr (enum ["ext4" "vfat" "btrfs" "xfs" "zfs"]);
        default = null;
        description = "Filesystem type for this mount.";
      };
      options = mkOption {
        type = listOf str;
        default = ["defaults"];
        description = "Mount option flags.";
      };
    };
  };
  #? Schema S8: devices.boot (LUKS mappings) only ever need `.device`.
  luksEntrySubmodule = submodule {
    options = {
      device = mkOption {
        type = str;
        description = "Underlying block device, addressed by UUID.";
      };
    };
  };
  #? Schema S8: devices.swap entries.
  swapEntrySubmodule = submodule {
    options = {
      device = mkOption {
        type = str;
        description = "Swap device, addressed by UUID.";
      };
    };
  };
  #? Schema S8: devices.display entries. Mirrors the resolved shape
  displayEntrySubmodule = submodule {
    options = {
      enable =
        mkEnableOption "Whether this display output is active."
        // {default = true;};
      brand = mkOption {
        description = "Display/panel manufacturer.";
        type = nullOr str;
        default = null;
      };
      resolution = mkOption {
        description = "Native resolution, format \"WxH\".";
        type = nullOr str;
        default = null;
      };
      refreshRate = mkOption {
        description = "Refresh rate in Hz.";
        type = nullOr float;
        default = null;
      };
      scale = mkOption {
        description = "Display scale factor.";
        type = float;
        default = 1.0;
      };
      position = mkOption {
        description = "Position in the virtual layout, format \"XxY\".";
        type = nullOr str;
        default = null;
      };
      size = mkOption {
        description = "Physical panel size, diagonal inches.";
        type = nullOr float;
        default = null;
      };
      priority = mkOption {
        description = "Display ordering priority; 0 is primary.";
        type = int;
        default = 0;
      };
      primary =
        mkEnableOption "Whether this display is the primary output.";
      layout = mkOption {
        type = submodule {
          options = {
            size = mkOption {
              type = submodule {
                options = {
                  width = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved display width in pixels.";
                  };
                  height = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved display height in pixels.";
                  };
                };
              };
              default = {};
              description = "Resolved display pixel size.";
            };
            position = mkOption {
              type = submodule {
                options = {
                  x = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved x coordinate in the compositor layout.";
                  };
                  y = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved y coordinate in the compositor layout.";
                  };
                };
              };
              default = {};
              description = "Resolved display position in the compositor layout.";
            };
          };
        };
        default = {};
        description = "Resolved compositor layout for this display.";
      };
    };
  };
  #? `system.nix` only ever acted at `core` scope (NixOS itself --
  core = {
    options.${top}.system = {
      #? S2 SYSTEM IDENTITY
      name = mkOption {
        type = str;
        default = host.name or "nixos";
        description = "Human-readable hostname.";
      };
      id = mkOption {
        type = nullOr str;
        default = host.id or null;
        description = "8-character hex machine identifier.";
      };
      description = mkOption {
        type = nullOr str;
        default = host.description or null;
        description = "Free-form host description.";
      };
      type = mkOption {
        type = nullOr (enum ["laptop" "desktop" "server" "vm" "container"]);
        default = host.type or null;
        description = "Physical form factor.";
      };
      class = mkOption {
        type = enum ["nixos" "darwin"];
        default = host.class or "nixos";
        description = "Operating-system family.";
      };
      platform = mkOption {
        type = str;
        default = host.system or "${host.arch}-${host.os}";
        description = "Nix system double, e.g. \"x86_64-linux\".";
      };
      #? Schema S2 marks this `required = true`. No fallback default
      stateVersion = mkOption (
        {
          type = str;
          description = "NixOS release baseline. Required -- must match hardware-configuration.nix at install time.";
        }
        // optionalAttrs (host.stateVersion or null != null) {
          default = host.stateVersion;
        }
      );
      #? S11 functionalities -- resolved/stored ONLY. Enablement of
      functionalities = mkOption {
        type = listOf (enum [
          "audio"
          "battery"
          "bluetooth"
          "efi"
          "gpu"
          "keyboard"
          "network"
          "secureboot"
          "storage"
          "video"
          "virtualization"
          "wired"
          "wireless"
        ]);
        default = host.functionalities or [];
        description = "Capability tags resolved for this host. Consumed by a separate module for actual enablement.";
      };
      #? S6 HARDWARE PROFILE
      specs = {
        machine = mkOption {
          type = nullOr (enum ["laptop" "desktop" "server" "vm" "container"]);
          default = specsSrc.machine or null;
          description = "Alias for top-level `type` at the specs scope.";
        };
        cpu = {
          arch = mkOption {
            type = nullOr str;
            default = (specsSrc.cpu or {}).arch or host.arch or null;
            description = "CPU architecture.";
          };
          brand = mkOption {
            type = nullOr (enum ["amd" "intel" "apple"]);
            default = (specsSrc.cpu or {}).brand or null;
            description = "CPU vendor.";
          };
          powerMode = mkOption {
            type = enum ["performance" "balanced" "powersave"];
            default = (specsSrc.cpu or {}).powerMode or "balanced";
            description = "Default CPU power profile.";
          };
          cores = mkOption {
            type = nullOr int;
            default = (specsSrc.cpu or {}).cores or null;
            description = "Physical core count.";
          };
        };
        gpu = {
          primary = {
            brand = mkOption {
              type = nullOr (enum ["amd" "intel" "nvidia"]);
              default = ((specsSrc.gpu or {}).primary or {}).brand or null;
              description = "Primary GPU vendor.";
            };
            busId = mkOption {
              type = nullOr str;
              default = ((specsSrc.gpu or {}).primary or {}).busId or null;
              description = "PCI bus ID, format \"PCI:D:B:F\".";
            };
            model = mkOption {
              type = nullOr str;
              default = ((specsSrc.gpu or {}).primary or {}).model or null;
              description = "Primary GPU model name.";
            };
          };
          secondary = {
            brand = mkOption {
              type = nullOr (enum ["amd" "intel" "nvidia"]);
              default = ((specsSrc.gpu or {}).secondary or {}).brand or null;
              description = "Secondary GPU vendor, if present.";
            };
            busId = mkOption {
              type = nullOr str;
              default = ((specsSrc.gpu or {}).secondary or {}).busId or null;
              description = "PCI bus ID, format \"PCI:D:B:F\".";
            };
            model = mkOption {
              type = nullOr str;
              default = ((specsSrc.gpu or {}).secondary or {}).model or null;
              description = "Secondary GPU model name.";
            };
          };
          mode = mkOption {
            type = enum ["integrated" "discrete" "hybrid" "off"];
            default = (specsSrc.gpu or {}).mode or "integrated";
            description = "Multi-GPU switching strategy.";
          };
        };
      };
      #? S7 KERNEL MODULES
      modules = mkOption {
        type = listOf str;
        default = host.modules or [];
        description = "Kernel module names passed to boot.initrd.availableKernelModules.";
      };
      #? S10 INTERFACE / BOOT
      interface = {
        bootLoader = mkOption {
          type = enum ["systemd-boot" "grub" "grub-efi"];
          default = interfaceSrc.bootLoader or "systemd-boot";
          description = "Boot loader backend.";
        };
        bootLoaderTimeout = mkOption {
          type = nullOr int;
          default = interfaceSrc.bootLoaderTimeout or null;
          description = "Seconds to show the boot menu. 0 = immediate, -1 = infinite.";
        };
        grubDevice = mkOption {
          type = str;
          default = interfaceSrc.grubDevice or "nodev";
          description = "Target device for GRUB install. Effectively required when bootLoader is \"grub\" or \"grub-efi\".";
        };
        osProber = mkEnableOption "GRUB os-prober detection of other installed operating systems";
        displayManager = mkOption {
          type = nullOr (enum ["dms" "gdm" "sddm" "regreet" "lightdm"]);
          default = interfaceSrc.displayManager or null;
          description = "Greeter / login manager.";
        };
        frontend = mkOption {
          type = nullOr (enum ["dms" "dank-material" "noctalia" "caelestia" "gnome" "plasma" "cosmic"]);
          default = interfaceSrc.frontend or null;
          description = "Graphical frontend layer that runs on top of the selected session backend.";
        };
        desktopEnvironment = mkOption {
          type = nullOr (enum ["plasma" "gnome" "xfce" "cinnamon"]);
          default = interfaceSrc.desktopEnvironment or null;
          description = "Full desktop environment, if used in place of a bare WM.";
        };
        windowManager = mkOption {
          type = nullOr (enum ["hyprland" "sway" "river" "dwm" "i3"]);
          default = interfaceSrc.windowManager or null;
          description = "Standalone window manager / compositor.";
        };
        displayProtocol = mkOption {
          type = nullOr (enum ["wayland" "x11"]);
          default = interfaceSrc.displayProtocol or null;
          description = "Display server protocol. Inferred from WM/DE if unset.";
        };
        keyboard = {
          modifier = mkOption {
            type = enum ["SUPER" "ALT" "CTRL"];
            default = (interfaceSrc.keyboard or {}).modifier or "SUPER";
            description = "Primary window-manager modifier key.";
          };
          swapCapsEscape = mkEnableOption "swapping Caps Lock and Escape";
        };
      };
      #? S8 DEVICES
      devices = {
        boot = mkOption {
          type = attrsOf luksEntrySubmodule;
          default = devicesSrc.boot or {};
          description = "LUKS/boot-time device mappings, keyed by mapper name.";
        };
        file = mkOption {
          type = attrsOf fsEntrySubmodule;
          default = devicesSrc.file or {};
          description = "Filesystem mounts, keyed by mount point.";
        };
        swap = mkOption {
          type = listOf swapEntrySubmodule;
          default = devicesSrc.swap or [];
          description = "Swap devices or files.";
        };
        network = mkOption {
          type = listOf str;
          default = devicesSrc.network or [];
          description = "Network interface names to bring up or configure.";
        };
        display = mkOption {
          type = attrsOf displayEntrySubmodule;
          default = devicesSrc.display or {};
          description = "Output/display layout, keyed by connector name.";
        };
      };
    };
    config = let
      #? Everything downstream reads the RESOLVED option tree, not raw
      cfg = config.${top}.system;
      bootLoaderConfig =
        if cfg.interface.bootLoader == "systemd-boot"
        then {
          systemd-boot.enable = true;
          efi.canTouchEfiVariables = true;
        }
        else if cfg.interface.bootLoader == "grub"
        then {
          grub = {
            enable = true;
            device = cfg.interface.grubDevice;
            efiSupport = false;
            useOSProber = cfg.interface.osProber;
          };
        }
        else if cfg.interface.bootLoader == "grub-efi"
        then {
          grub = {
            enable = true;
            device = cfg.interface.grubDevice;
            efiSupport = true;
            useOSProber = cfg.interface.osProber;
          };
          efi.canTouchEfiVariables = true;
        }
        else {}; #TODO: Allow other bootloders
    in
      {
        assertions = [
          {
            assertion = elem cfg.interface.bootLoader ["systemd-boot" "grub" "grub-efi"];
            message = "${top}.system.interface.bootLoader must be one of \"systemd-boot\", \"grub\", \"grub-efi\"; got \"${cfg.interface.bootLoader}\" for host \"${cfg.name}\".";
          }
        ];
        networking.hostName = mkDefault cfg.name;
        system.stateVersion = mkDefault cfg.stateVersion;
        nixpkgs.hostPlatform = mkDefault cfg.platform;
        boot = {
          loader =
            bootLoaderConfig
            // optionalAttrs (cfg.interface.bootLoaderTimeout != null) {
              timeout = cfg.interface.bootLoaderTimeout;
            };
          initrd = optionalAttrs ((host.modules or []) != [] || (devicesSrc.boot or {}) != {}) {
            availableKernelModules = cfg.modules;
            luks.devices = cfg.devices.boot;
          };
        };
      }
      // optionalAttrs ((devicesSrc.file or {}) != {}) {fileSystems = cfg.devices.file;}
      // optionalAttrs ((devicesSrc.swap or []) != []) {swapDevices = cfg.devices.swap;};
  };
  home = {};
in {inherit core home;}

{
  lix,
  top,
  host,
  ...
}: let
  inherit (lix.users) mkCoreUsers mkSudoRules mkHomeUsers;
  inherit (lix.options) mkOption;
  inherit (lix.types) attrsOf anything;
  data = host.users or {};
  mk = scope: _: {
    options.${top}.users = mkOption {
      type = attrsOf anything;
      default = {};
      description = "User account declarations. Overrides host.api default specifications.";
    };
    config =
      {${top}.users = data;}
      // (
        if scope == "core"
        then {
          users = mkCoreUsers host;
          security.sudo = {
            execWheelOnly = true;
            extraRules = mkSudoRules host;
          };
          home-manager.users = mkHomeUsers host;
        }
        else {}
      );
  };
in {
  core = mk "core";
  home = mk "home";
}

{lix, ...} @ args: let
  inherit (lix.modules) mkModules;
  moduleArgs = {
    base = ./.;
    excludes = [
      "displays"
      "secrets"
      "services"
    ];
  };
in
  mkModules (args // moduleArgs)

{
  lix,
  api,
  host,
  ...
} @ args: let
  inherit (lix.modules) mkModules;
  inherit (lix.options) mkEnableOption mkOption;
  inherit (lix.types) asFloat int nullOr str submodule;
  data = host.devices.display or (api.displays or {});
  moduleArgs = {
    inherit data;
    base = ./.;
    path = args.path or ["displays"];
    recurse = true;
    declareRegistry = true;
    extraArgs = {inherit type;};
  };
  type = submodule {
    options = {
      enable =
        mkEnableOption "display output"
        // {default = true;};
      brand = mkOption {
        type = nullOr str;
        default = null;
        description = "Display/panel manufacturer.";
      };
      resolution = mkOption {
        type = nullOr str;
        default = null;
        description = "Native resolution, format \"WxH\".";
      };
      refreshRate = mkOption {
        type = nullOr asFloat;
        default = null;
        description = "Refresh rate in Hz.";
      };
      scale = mkOption {
        type = asFloat;
        default = 1.0;
        description = "Display scale factor.";
      };
      position = mkOption {
        type = nullOr str;
        default = null;
        description = ''
          Display position input. May be semantic ("left", "right",
          "top", "bottom", "center") or exact coordinates in "XxY" form.
        '';
      };
      layout = mkOption {
        type = submodule {
          options = {
            size = mkOption {
              type = submodule {
                options = {
                  width = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved display width in pixels.";
                  };
                  height = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved display height in pixels.";
                  };
                };
              };
              default = {};
              description = "Resolved display pixel size.";
            };
            position = mkOption {
              type = submodule {
                options = {
                  x = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved x coordinate in the compositor layout.";
                  };
                  y = mkOption {
                    type = int;
                    default = 0;
                    description = "Resolved y coordinate in the compositor layout.";
                  };
                };
              };
              default = {};
              description = "Resolved display position in the compositor layout.";
            };
          };
        };
        default = {};
        description = "Resolved compositor layout for this display.";
      };
      size = mkOption {
        type = nullOr asFloat;
        default = null;
        description = "Physical panel size, diagonal inches.";
      };
      priority = mkOption {
        type = int;
        default = 0;
        description = "Display ordering priority; derived from API list order.";
      };
      primary =
        mkEnableOption "Whether this display is the primary output. Derived from API list order."
        // {default = false;};
    };
  };
in
  mkModules (args // moduleArgs)

{
  lix,
  top,
  path,
  registry,
  entry,
  ...
}: let
  inherit (lix.attrsets) hasAttrByPath optionalAttrs;
  inherit (lix.displays) mkHyprland mkNiri;
  inherit (lix.lists) init;
  inherit (lix.modules) mkDefault mkMerge;
  inherit (lix.options) mkModuleArgs mkOption;
  inherit (lix.types) attrs attrsOf;
  path' = path;
  mkMod = {
    config,
    options ? {},
    pkgs ? {},
    scope ? "core",
    path ? path',
  }: let
    module = mkModuleArgs {
      inherit config options pkgs top scope;
      path = init path;
    };
    cfg = module.get.config.module;
    opt = module.set.options.module;
    hasHyprland =
      (config.programs.hyprland.enable or false)
      || (config.wayland.windowManager.hyprland.enable or false)
      || (config.${top}.interface.backends.hyprland.enable or false);
    hasNiri =
      (config.programs.niri.enable or false)
      || (config.${top}.interface.backends.niri.enable or false);
    outputs = {
      monitors = registry;
      hyprland = optionalAttrs hasHyprland {
        monitor = (mkHyprland registry).monitors;
      };
      niri = optionalAttrs hasNiri (mkNiri registry);
    };
    fields = {
      monitors = mkOption {
        type = attrsOf entry;
        default = outputs.monitors;
        description = "Resolved, compositor-agnostic output/display layout, keyed by connector name.";
      };
      hyprland = mkOption {
        type = attrs;
        default = outputs.hyprland;
        description = "Resolved Hyprland monitors config; empty when Hyprland is not enabled.";
      };
      niri = mkOption {
        type = attrs;
        default = outputs.niri;
        description = "Resolved Niri outputs config; empty when Niri is not enabled.";
      };
    };
  in {
    inherit cfg fields;
    options = opt fields;
    config = opt {
      monitors = mkDefault fields.monitors.default;
      hyprland = mkDefault fields.hyprland.default;
      niri = mkDefault fields.niri.default;
    };
  };
  mk = scope: {
    config,
    options ? {},
    pkgs ? {},
    ...
  }: let
    mod = mkMod {inherit config options pkgs scope;};
  in {
    inherit (mod) options;
    config = mkMerge [
      mod.config
      (
        if scope == "core"
        then {}
        else
          optionalAttrs (hasAttrByPath ["wayland" "windowManager" "hyprland" "settings"] options) {
            wayland.windowManager.hyprland.settings = mod.cfg.hyprland;
          }
          // optionalAttrs (hasAttrByPath ["programs" "niri" "settings"] options) {
            programs.niri.settings.outputs = mod.cfg.niri;
          }
      )
    ];
  };
in {
  core = mk "core";
  home = mk "home";
}

{
  lix,
  api,
  top,
  host,
  ...
} @ args: let
  inherit (lix.options) mkOption;
  inherit (lix.types) isString nullAny nullStr;
  mkModule = scope: {config, ...}: let
    mod = lix.modules.mkModuleArgs (args // {inherit config scope;});
    inherit (mod) get set;
    inherit (get) user;
    primary = api.interface.primaryOf {inherit user host;};
    secondary = api.interface.secondaryOf {inherit user host;};
    tertiary = api.interface.tertiaryOf {inherit user host;};
    resolveAppName = name: api.applications.aliases.${name} or name;
    inflate = entry:
      if entry == null
      then null
      else let
        rawName =
          if isString entry
          then entry
          else entry.name or (throw "interface: cannot resolve application name from ${builtins.toJSON entry}");
        name = resolveAppName rawName;
        registryEntry =
          api.applications.registry.${name}
      or (throw "interface: '${name}' (resolved from '${rawName}') not found in dots.applications.registry");
        liveConfig = config.${top}.applications.${name} or {};
        merged = registryEntry // liveConfig // {inherit name;};
      in
        removeAttrs merged ["applications" "bindings" "variables"];
    nameOf = entry:
      if entry == null
      then null
      else entry.name or null;
  in {
    options = set.opt {
      session = mkOption {
        type = nullStr;
        default = primary.name or null;
        description = "Name of the primary session, for display-manager configuration.";
      };
      frontend = mkOption {
        type = nullStr;
        default = nameOf (inflate (primary.frontend or null));
        description = "Name of the resolved frontend application for the primary session, or null.";
      };
      greeter = mkOption {
        type = nullStr;
        default = nameOf (inflate (primary.greeter or null));
        description = "Name of the resolved greeter application for the primary session, or null.";
      };
      protocol = mkOption {
        type = nullAny;
        default = let
          proto = primary.protocol or null;
        in
          if proto == null
          then null
          else {
            name = proto;
            packages = [];
          };
        description = "Display protocol of the primary session, as { name; packages; }.";
      };
      primary = mkOption {
        type = nullAny;
        default =
          primary
          // {
            frontend = inflate (primary.frontend or null);
            greeter = inflate (primary.greeter or null);
          };
        description = "The primary/default resolved interface session.";
      };
      secondary = mkOption {
        type = nullAny;
        default =
          if secondary == null
          then null
          else
            secondary
            // {
              frontend = inflate (secondary.frontend or null);
              greeter = inflate (secondary.greeter or null);
            };
        description = "The secondary resolved interface session, if any.";
      };
      tertiary = mkOption {
        type = nullAny;
        default =
          if tertiary == null
          then null
          else
            tertiary
            // {
              frontend = inflate (tertiary.frontend or null);
              greeter = inflate (tertiary.greeter or null);
            };
        description = "The tertiary resolved interface session, if any.";
      };
    };
    config = {};
  };
in {
  core.imports = [(mkModule "core")];
  home.imports = [(mkModule "home")];
}

