      src = ./.;
      data = ./data;
      api = ./data;
      dbg = ./debug;
      documentation = ./documentation;
      configuration = ./configuration;
      templates = ./templates;
      shells = ./development;
      utilities = ./utilities;
      secrets = ./configuration/secrets;
      libraries = ./libraries;
    };
  };
  defaults = {
    tags = ["core" "home"];
    labels.application = {
      browser = "Browser launch";
      editor = "Editor launch";
      visual = "Visual/IDE launch";
      launcher = "Launcher trigger";
      terminal = "Terminal launch";
    };
    host = let
      inherit (builtins) isAttrs getEnv;
      env = {
        host = getEnv "HOSTNAME";
        name = getEnv "NAME";
      };
    in
      if isAttrs flake && ((flake.currentHost or "") != "")
      then flake.currentHost
      else if (env.host != "")
      then env.host
      else if (env.name != "")
      then env.name
      else "Preci";
  };
  libraries =
    import paths.store.libraries
    {inherit defaults flake names paths;};
in
  libraries.merged.mkSrc {inherit libraries;}

