      };
      nix-darwin = {
        input = "nixDarwin";
        scopes = ["core" "infrastructure"];
      };
      nixos-anywhere = {
        input = "deployAnywhere";
        scopes = ["deployment"];
      };
      nixpkgs = {
        input = "nixCore";
        scopes = ["core" "infrastructure"];
      };
      nixpkgs-stable = {
