  exports = {
    scoped = {
      inherit mkModules mkModuleArgs mkCfg mkCfgIf mkOpt mkIf' mkProgramToggle mkAutostartCollector;
      ingest = mkModules;
      configure = mkModuleArgs;
      inherit (backends) mkHyprlandBinds mkNiriBinds mkBackendOptions;
    };
    global = {inherit mkModules mkModuleArgs mkCfgIf mkIf' mkProgramToggle mkAutostartCollector;};
  };
  inherit
    (attrsets)
    asAttrs
    foldMerge
    genAttrs
    hasAttr
    hasAttrByPath
    namesOf
    mapAttrs
    mapAttrsToList
    mkNamespaced
    asAttrsIf
    recursiveUpdate
    setAttrByPath
    valuesOf
    attrByPath
    isNotEmptyAttr
    ;
  inherit (ingestion) collectSpecs;
  inherit
    (lists)
    asList
    asListIf
    concatMap
    elem
    filter
    foldl'
    hasAny
    head
    init
    last
    length
    ;
  inherit (assembly) mkBindings mkRegistryVariables;
  inherit (modules) mkIf mkMerge mkDefault mkForce;
  inherit (options) mkAppOption mkEnable mkOption;
  inherit (strings) concatStringsSep toSentenceCase;
  inherit (types) attrs isList isNotEmpty isString;
  mkModules = args @ {
    base,
    data ? (
      let
        domain =
          if path != []
          then (last path)
          else null;
      in
        args.extraArgs.registry or (
          asAttrsIf
          (domain != null && api ? ${domain}.registry)
          api.${domain}.registry
        )
    ),
    excludes ? null,
    extraArgs ? {},
    includeFiles ? true,
    includes ? [],
    path ? [],
