    get = {
      inherit host scope users;
      names = let
        base =
          if isNotEmpty top
          then top
          else names.src;
        raw =
          if path != []
          then last path
          else null;
        domain =
          if path != []
          then head path
          else null;
        registry =
          if domain != null
          then api.${domain}.registry or {}
          else {};
        collect = {
          name ? null,
          keys ? [],
