                ["wayland" "windowManager"]
                ["programs"]
                ["services"]
              ]
              else [
                ["programs"]
                ["services" "desktopManager"]
                ["services" "xserver" "windowManager"]
                ["services"]
              ]
            else if hasAny ["service" "daemon"] categories
