            filter
            (prefix: hasAttrByPath (prefix ++ [name]) options)
            known;
        in
          if valid != []
          then head valid
          else head known;
        collectAliases = args:
          collect {
            name = args.name or canonical;
            keys = args.keys or ["alias" "aliases"];
          };
        collectCategories = args:
          collect {
            name = args.name or canonical;
            keys = args.keys or ["category" "categories"];
          };
        canonical =
          if registry ? ${raw}
          then raw
          else let
            matchingKeys = filter (name:
