      in {
        validate = target:
          if elem target targets
          then get.paths.${target}
          else
            throw "Invalid target: '${target}'. Valid targets are: ${
              concatStringsSep ", " targets
            }";
        main = [];
        custom = [get.names.base];
        module = get.paths.custom ++ path';
        parent = init get.paths.module;
