      top =
        if top != null
        then top
        else get.names.custom;
      config =
        genAttrs targets
        (target: set.config {inherit target;});
      cfg = get.config.module;
      cfgOr = key: let
        fromConfig = attrByPath (get.paths.module ++ [key]) null config;
      in
        if fromConfig != null
        then fromConfig
        else
          attrByPath
          (get.paths.module ++ [key]) (extraArgs.${key} or null)
          osConfig;
      options =
        genAttrs targets
