      else if isAttrs value
      then mapAttrs (_: fn (depth - 1)) value
      else value;
  in
    fn level;
  inspectJSON = level: value:
    toJSON (inspect level value);
  getBySpec = input: spec:
    assert withContext {
      name = "attrsets.getBySpec";
      assertion = isNull input || isAttrs input;
      message = "expected input to be an attrset or null, got ${typeOf input}";
      context = "evaluating attrsets.getBySpec";
    };
      if input == null
      then null
      else if isList spec
      then attrByPath spec null input
      else if isString spec && hasAttr spec input
      then getAttr spec input
      else null;
  findFirst = {
    sets,
    specs,
    default ? null,
  }:
    assert withContext {
      name = "attrsets.findFirst'";
      assertion = isList sets && isList specs;
      message = "expected sets and specs to be lists";
      context = "evaluating attrsets.findFirst";
    };
      findFirstList (x: x != null) default
      (concatMap (input: map (spec: getBySpec input spec) specs) sets);
  resolveBySpecs = {
    input,
    specs,
    default ? null,
  }:
    assert withContext {
      name = "attrsets.resolveBySpecs";
      assertion = (input == null || isAttrs input) && isList specs;
      message = "expected input to be an attrset or null, and specs to be a list";
      context = "evaluating attrsets.resolveBySpecs";
    };
      findFirst {
        sets = [input];
        inherit specs default;
      };
  mergeUnique = {
    items,
    attrs,
    what ? "attributes",
    owner ? (name: name),
  }:
    foldl'
    (
      acc: name: let
        incoming = attrs name;
        collisions = filter (key: hasAttr key acc) (namesOf incoming);
      in
        if collisions == []
        then acc // incoming
        else
          throw ''
            ${what}: collision(s) detected in '${owner name}':
              ${concatStringsSep ", " collisions}
            Each merged attribute name must be unique.
          ''
    )
    {}
    (namesOf items);
  getOrderedOr = {
    key,
    set,
    default ? null,
  }:
    if hasAttr key set
    then getAttr key set
    else default;
  toOrdered = {value}: let
    count =
      if isList value
      then length value
      else 1;
  in
    listToAttrs (
      map (position: {
        name = toString (position + 1);
        value = nthOr {
          inherit position value;
        };
      }) (genList (x: x) count)
    );
  mapOrdered = set:
    mapAttrs (_: value: toOrdered {inherit value;}) set;
  parseOrdered = value: let
    ordered =
      if isAttrs value
      then value
      else toOrdered {inherit value;};
    primary = getOrderedOr {
      key = "1";
      set = ordered;
    };
    secondary = getOrderedOr {
      key = "2";
      set = ordered;
    };
    tertiary = getOrderedOr {
      key = "3";
      set = ordered;
    };
    preferred = primary;
    fallback = secondary;
    default =
      if isList value
      then
        if value == []
        then null
        else
          nthOr {
            position = (length value) - 1;
            inherit value;
          }
      else if isAttrs value
      then
        getOrderedOr {
          key = "default";
          set = value;
          default = primary;
        }
      else value;
  in
    ordered
    // {inherit primary secondary tertiary preferred fallback default;};
  mapParsedOrdered = set: mapAttrs (_: parseOrdered) set;
  mkNamespaced = payload: let
    args = extractArgs {
      args = payload;
      required = ["sets"];
      defaults = {transformation = "camelCase";};
    };
    styleMap =
      {
        camelCase = prefix: name:
          if name == ""
          then prefix
          else "${prefix}${toUpper (substring 0 1 name)}${substring 1 (-1) name}";
        shell = prefix: name:
          if name == ""
          then toUpper prefix
          else "${toUpper prefix}_${toUpper name}";
        none = prefix: name: "${prefix}${name}";
      }
      // {POSIX = styleMap.shell;};
    formatName = styleMap.${args.transformation} or styleMap.camelCase;
  in
    concatMapAttrs (
      prefix: attrset:
        listToAttrs (map (name: {
          name = formatName prefix name;
          value = attrset.${name};
        }) (namesOf attrset))
    )
    args.sets;
  foldMerge = list:
    foldl' recursiveUpdate {} (filter isAttrs list);
  normalize = args: let
    isDescriptor =
      isAttrs args
      && args ? flag
      && isString args.flag
      && args ? value;
    input = {
      flag =
        if isDescriptor
        then args.flag
        else "enable";
      value =
        if isDescriptor
        then args.value
        else args;
    };
    inherit (input) flag value;
    resolved = {
      ${flag} = true;
      inherit value;
    };
    type = typeOf value;
    list = genAttrs value (_: removeAttrs resolved ["value"]);
    bool = {${flag} = value;};
    set =
      if value ? ${flag} || value ? value
      then (removeAttrs value ["value"]) // {${flag} = value.${flag} or true;}
      else mapAttrs (_: value: normalize {inherit flag value;}) value;
    handlers = {inherit list bool set;};
  in
    handlers.${type} or resolved;
  extractArgs = {
    args ? null,
    payload ? null,
    required ? [],
    optional ? allowed,
    defaults ? {},
    allowed ? required ++ (namesOf defaults),
    legacyMapKey ? (head required),
  }: let
    value =
      if args != null
      then args
      else if payload != null
      then payload
      else throw "extractArgs: no args or payload provided";
    check =
      (isAttrs value)
      && (all (req: hasAttr req value) required)
      && (
        all
        (key: elem key (uniqueStrings (allowed ++ optional)))
        (namesOf value)
      );
  in
    if check
    then defaults // value
    else defaults // {"${legacyMapKey}" = value;};
in
  exports

{
  debug,
  types,
  strings,
  ...
}: let
  exports = {
    scoped = {
      inherit
        mkTest
        mkTest'
        mkThrows
        assertMsgFunc
        assertWithContext
        warnWithContext
        expect
        ;
      withContext = assertWithContext;
    };
    global = {
      inherit
        assertWithContext
        expect
        warnWithContext
        ;
    };
  };
  inherit (debug) addErrorContext assertMsg deepSeq traceIf tryEval;
  inherit (types) isAttrs isBool isPath isString typeOf;
  inherit (strings) toJSON;
  assertMsgFunc = {
    name,
    assertion,
    message,
  }:
    assertMsg assertion "${name}: ${message}";
  assertWithContext = {
    name,
    assertion,
    message,
    context,
  }:
    addErrorContext
    "while ${context}"
    (assert assertMsgFunc {
      inherit name assertion message;
    }; true);
  _build = desired: outcome: command: let
    value = deepSeq outcome outcome;
  in {
    inherit desired command;
    result = value;
    passed = desired == value;
  };
  warnWithContext = {
    name,
    assertion,
    message,
    context,
  }:
    deepSeq
    (traceIf (!assertion) "[${name}] while ${context}: ${message}" true)
    assertion;
  /**
  Create a named test case with desired output, outcome expression, and an
  optional command string for display in test results.
  ```nix
  mkTest :: { desired :: a, outcome :: a, command :: string? } -> Test
  ```
  ```nix
  mkTest {
    desired = "foo-bar";
    command = ''normalize "Foo Bar"'';
    outcome = normalize "Foo Bar";
  }
  ```
  */
  mkTest = {
    desired,
    outcome,
    command ? null,
  }:
    _build desired outcome command;
  /**
  Positional shorthand for `mkTest` - no command string.
  Useful in enum and validator test blocks where the expression is self-evident.
  ```nix
  mkTest' :: a -> a -> Test
  ```
  ```nix
  validatesRust = mkTest' true  (languages.validator.check "rust")
  correctCount  = mkTest' 4     (length cpuBrands.values)
  ```
  */
  mkTest' = desired: outcome: _build desired outcome null;
  /**
  Create a test case that expects evaluation to throw.
  Uses `builtins.tryEval` to catch the error - the test passes only if
  evaluation fails.
  ```nix
  mkThrows :: a -> Test
  ```
  ```nix
  mkThrows (validate { fnName = "f"; argName = "x"; desired = "set"; predicate = isAttrs; outcome = "oops"; })
  ```
  */
  mkThrows = outcome:
    mkTest {
      desired = {
        success = false;
        value = false;
      };
      outcome = tryEval outcome;
    };
  expect = {
    type,
    value,
    context,
    name,
  }:
    assert assertWithContext {
      inherit name context;
      assertion =
        if type == "bool"
        then isBool value
        else if type == "attrs"
        then isAttrs value
        else if type == "path"
        then (isPath value || (isString value && value != ""))
        else false;
      message = "Expected type '${type}', but got '${typeOf value}' with value: ${toJSON value}";
    }; value;
in
  exports

{
  external ? null,
  bootstrap ? null,
  flake ? {},
  paths ? {},
  defaults ? {},
  names ? {},
}: let
  bootstrap' =
    if bootstrap != null
    then bootstrap
    else
      import (
        paths.store.libraries.bootstrap or (
          paths.libraries.bootstrap or (
            paths.bootstrap or ../internal/base
          )
        )
      );
  external' =
    if external != null
    then external
    else
      import (
        paths.store.libraries.external or (
          paths.libraries.external or (
            paths.external or ../external
          )
        )
      ) {inherit defaults flake names paths;};
  flake' = external'.flake or flake;
  inherit (bootstrap'.attrsets) merge;
  inherit (bootstrap'.config) mkLibrary mkPaths;
  _ =
    merge
    (merge external' bootstrap')
    {
      bootstrap = bootstrap';
      external = external';
      flake = flake';
      defaults = merge defaults (
        merge {
          host = "TheExample";
          excludes.paths = [
            "archive"
            "backup"
            "review"
            "temp"
            "default.nix"
            "flake.nix"
          ];
          tags = ["core" "home"];
        }
        (flake'.defaults or {})
      );
      paths = mkPaths {
        paths = merge paths (
          merge {
            store = {
              src = ../../.;
              data = ../../data;
              api = ../../data;
            };
            local.src = "/etc/nixos";
          }
          (flake'.paths or {})
        );
      };
      names = merge names (
        merge {
          src = "dots";
          lib = "lix";
          top = "_";
        }
        (flake'.names or {})
      );
    };
  excludes = ["default" "base" "bootstrap"];
  extra = merge external' bootstrap';
in
  mkLibrary {
    inherit _ excludes extra;
    base = ./.;
    enableAliases = false;
    enableExtras = false;
  }

{
  attrsets,
  filesystem,
  lists,
  paths,
  strings,
  comparison,
  types,
  ...
}: let
  exports = {
    scoped = {inherit entrypoint entrypoints mkPaths mkUserPaths bat;};
    global = {
      inherit
        entrypoint
        entrypoints
        mkPaths
        mkUserPaths
        toPathList
        ;
    };
  };
  inherit (lists) filter concatLists head sort optionals;
  inherit (comparison) lessThan;
  inherit (attrsets) attrNames mapAttrs filterAttrs;
  inherit (strings) split' concatStringsSep quote stringLength substring hasPrefix;
  inherit (types) isAttrs isPath isString typeOf;
  inherit (filesystem) path readDir readFile readFileType;
  /**
  Boundary-safe prefix check: true if `value` is exactly `root`, or sits
  *under* `root` separated by a real path boundary ("/"). Plain `hasPrefix`
  would wrongly match "/home/x/dots-backup" against root "/home/x/dots";
  this requires the next character after the prefix to be "/".
  ```nix
  isUnder :: (Path|String) -> (Path|String) -> Bool
  ```
  */
  isUnder = root: value: let
    r = toString root;
    v = toString value;
  in
    v == r || hasPrefix (r + "/") v;
  /**
  Classify a single path-like value against the two known roots (the
  project's store src and the host's local src).
  Real Nix path literals are always store-relative by construction -- a
  path value is already copied into the store, so it cannot mean anything
  else, even if it happens to look like it lives under the local root.
  Only strings are ambiguous about which root (if any) they relate to.
  Returns one of:
  - { root = "store";    stem  :: String } -- under (or is) the store root
  - { root = "local";    stem  :: String } -- under the local root
  - { root = "absolute"; value :: String } -- unrelated to either root
  ```nix
  classify :: { store :: Path; local :: String } -> (Path|String) -> AttrSet
  ```
  */
  classify = {
    store,
    local,
  }: value: let
    storeAsStr = toString store;
    localAsStr = toString local;
    stemFrom = root: substring (stringLength root) (-1) (toString value);
  in
    if isPath value || isUnder storeAsStr value
    then {
      root = "store";
      stem = stemFrom storeAsStr;
    }
    else if isUnder localAsStr value
    then {
      root = "local";
      stem = stemFrom localAsStr;
    }
    else {
      root = "absolute";
      value = toString value;
    };
  /**
  Build a normalized pair of path sets -- one for the Nix store, one for the
  local filesystem -- from an optional source-tree configuration.
  Every extra key (beyond `src`) in either `store` or `local` is classified
  independently against both roots:
  - Nix path literals, or strings under the store root, get rebased onto
    both `store.src` and `local.src` -- they have a meaningful counterpart
    on both sides.
  - Strings under the local root get rebased onto `local.src`, and mirrored
    onto `store.src` as well, since they describe the same project-relative
    stem just spelled from the local checkout's perspective.
  - Strings under neither root (e.g. "/home/user/Pictures") are genuinely
    absolute, local-only paths -- they appear in `local` verbatim and have
    no `store` entry at all.
  When `local` is an attrset and `meta.usedKey` is given, whichever key
  actually supplied `src` (the first hit in the host's own resolution
  order -- e.g. `src`, then `dots`, then `home`) is excluded from the
  extras. Any *other* key, including `home` or `dots` if they weren't the
  one used to derive `src`, is kept and classified normally -- e.g. a host
  can still define `home` to mean "primary user's home directory" as a
  plain extra, as long as it wasn't also the key chosen to resolve `src`.
  `meta` is resolution bookkeeping only -- it never appears in the output.
  Note: `mkPaths` has no concept of "users" -- it only classifies and
  rebases path-like values it's handed. Deriving defaults like `pictures`
  or `downloads` from a user record is a separate policy concern; see
  `mkUserPaths` below, which produces a plain attrset you can merge into
  `local` before calling this function.
  ```nix
  mkPaths :: {
    store ? :: Path | { src :: Path; [name :: Path | String] };
    local ? :: String | { src :: String; [name :: Path | String] };
    meta ? :: { usedKey :: String? };
  } -> {
    store :: { src :: StorePath; [name :: StorePath] };
    local :: { src :: String;    [name :: String]    };
  }
  ```
  store
  : Either a path literal (the Nix store root of the project) or an
    attribute set whose `src` key is a path literal and whose remaining
    keys are paths to classify and track. Defaults to `paths.store`.
  local
  : Either a string (the local checkout root) or an attribute set whose
    `src` key is that string and whose remaining keys are extra host paths
    (e.g. `pictures`, `downloads`) to classify and track. If omitted,
    `toString store.src` is used as the local root. Defaults to
    `paths.local`.
  meta
  : Resolution bookkeeping, kept separate from `local` so it can never leak
    into the output as a path entry. `meta.usedKey`, if given, names which
    key of `local` was the actual source of `src`, so it can be excluded
    from the extras without blacklisting `dots`/`home` by name.
  Builtins
  : `isAttrs`, `isPath`, `isString`, `mapAttrs`, `path`, `removeAttrs`,
    `stringLength`, `substring`, `toString`
  attrsets
  : `filterAttrs`, `mapAttrs`
  strings
  : `hasPrefix`
  ```nix
  mkPaths { store.src = ./.; }
  mkPaths {
    store = { src = ./.; libraries = ./libraries; };
    local = {
      src       = "/etc/nixos";
      pictures  = "/home/user/Pictures";
      downloads = "/home/user/Downloads";
    };
  }
  mkPaths {
    store = { src = ./.; };
    local = { home = "/home/user/dots"; };
    meta.usedKey = "home";
  }
  mkPaths {
    store = { src = ./.; };
    local = { src = "/home/user/dots"; home = "/home/user"; };
  }
  ```
  */
  mkPaths = {
    store ? paths.store,
    local ? paths.local or null,
    meta ? {},
  }: let
    _name = "filesystem::mkPaths";
    args = {
      store = store.src or store;
      local =
        if local == null
        then toString args.store
        else if isAttrs local
        then
          local.src
        or (throw "${_name}: 'local' attrset is missing a 'src' string. Given paths are [${
            concatStringsSep ", " (attrNames local)
          }].")
        else local;
    };
    src = {
      store = path {
        path = args.store;
        name = "source";
      };
      local = toString args.local;
    };
    extrasOf = value:
      if isAttrs value
      then
        removeAttrs value (
          ["src"]
          ++ (
            optionals
            (meta ? usedKey && value ? ${meta.usedKey})
            [meta.usedKey]
          )
        )
      else {};
    define = classify {inherit (args) store local;};
    classified =
      mapAttrs (_: define) (extrasOf store)
      // mapAttrs (_: define) (extrasOf local);
    entries = {
      store = filterAttrs (_: kind: kind.root == "store") classified;
      relative = filterAttrs (_: kind: kind.root == "local") classified;
      absolute = filterAttrs (_: kind: kind.root == "absolute") classified;
    };
    rebased = entries.store // entries.relative;
  in
    #TODO: Use debug.withContext
    assert if isAttrs store || isPath store
    then true
    else throw "${_name}: 'store' must be a path literal or an attribute set containing file mappings.";
    assert !isAttrs store
    || (store ? src
      && (
        (isPath store.src)
        || (isString store.src && hasPrefix "/" store.src)
      ))
    || throw "${_name}: 'store' set is missing a valid path for 'src'. Given paths are [${
      concatStringsSep ", " (attrNames store)
    }].";
    assert (local == null)
    || isString local
    || isAttrs local
    || throw "${_name}: 'local' must be a string, an attribute set with 'src', or null."; {
      store =
        {src = src.store;}
        // mapAttrs (_: entry: src.store + entry.stem) rebased;
      local =
        {src = src.local;}
        // mapAttrs (_: entry: src.local + entry.stem) rebased
        // mapAttrs (_: entry: entry.value) entries.absolute;
    };
  /**
  Derive standard per-user folder defaults (Downloads, Pictures, Documents,
  Music, Videos) from a user record's `home` field.
  This is deliberately separate from `mkPaths`, which has no concept of
  "what a user is" -- it only classifies and rebases path-like values
  against known roots. `mkUserPaths` is the policy layer that decides
  what a sensible default folder layout looks like for a given home
  directory; `mkPaths` remains the mechanism layer that doesn't care where
  those defaults came from once they're plain strings. Merge the result
  into `local` before calling `mkPaths`, at the lowest precedence, so any
  global default or host override still wins over the user-derived guess.
  ```nix
  mkUserPaths :: { user :: { home :: String; ... }; overrides :: AttrSet? } -> AttrSet
  ```
  user
  : A user record (e.g. `host.users.primary.value`) with at least a `home`
    string field. Defaults are built as `"${user.home}/<Folder>"`.
  overrides
  : Explicit values to use instead of the computed default for any key,
    merged on top (override wins). Lets a host redefine e.g. `downloads`
    to point somewhere nonstandard without losing the other defaults.
  Builtins
  : none beyond string interpolation
  ```nix
  mkUserPaths { user = { home = "/home/craole"; }; }
  mkUserPaths {
    user = { home = "/home/craole"; };
    overrides.downloads = "/mnt/data/Downloads";
  }
  ```
  */
  mkUserPaths = {
    user,
    overrides ? {},
  }: let
    _name = "filesystem::mkUserPaths";
    home =
      user.home or "/home/${user.name}";
    defaults = {
      downloads = "${home}/Downloads";
      pictures = "${home}/Pictures";
      projects = "${home}/Projects";
      documents = "${home}/Documents";
      music = "${home}/Music";
      videos = "${home}/Videos";
    };
  in
    assert isAttrs user
    || throw "${_name}: 'user' must be an attribute set.";
    assert isString home
    || throw "${_name}: 'user.home' must be a string.";
      defaults // overrides;
  entrypoints.nix = let
    ext = "nix";
    candidates = map (name: "${name}.${ext}") [
      "default"
      "shell"
      "flake"
      "configuration"
      "_"
    ];
    primary = head candidates;
  in {inherit ext candidates primary;};
  entrypoint = entrypoints.nix.primary;
  /**
  Split a path or path-like string into its individual components.
  Strips a leading `./` prefix before splitting. The special input `"."` returns
  `["."]` rather than an empty list.
  ```nix
  toPathList :: Path   -> [String]
  toPathList :: String -> [String]
  ```
  path
  : A Nix path literal or a string. Recognised string forms: `"."`,
    `"./rel/path"`, `"rel/path"`, `"/abs/path"`.
  ```nix
  toPathList ./lib/util.nix
  toPathList "."
  toPathList "/abs/path"
  toPathList "./foo/bar/baz"
  ```
