    if pathStr == "."
    then ["."]
    else filter (x: x != "") (split' "/" clean);
  /**
  Read a file, or recursively collect and label all regular files in a directory.
  - Single file:
    - If `label` is provided, it is shown directly.
    - Else if the input `path` is a string, it is shown directly.
    - Else if `root` is provided, the file is shown relative to `root`.
    - Else the absolute/normalised Nix path string is shown.
  - Directory:
    - Walks recursively in lexicographic order.
    - If `root` is provided, every file is shown relative to `root`.
    - Else every file is shown relative to the walked directory.
  Path headers use this format:
  ```
  #************************************************
  #> STORE: /nix/store/…-source
  #> LOCAL: /path/to/flake
  #> STEMS: [ "relative" "path" "parts" "file.nix" ]
  #************************************************
  ```
  When store and local roots are identical, a single `#> ROOT:` line is shown
  instead of the `STORE` / `LOCAL` pair.
  Symlinks and unknown filesystem entries are silently skipped.
  ```nix
  bat :: Path -> String
  bat :: String -> String
  bat :: {
    path       :: Path | String;
    root      ?: Path | String | { store :: Path; local :: Path | String };
    label     ?: String;
    name      ?: String;
  } -> String
  ```
  path
  : A path literal or path-like string pointing to a file or directory.
    Accepted string prefixes: `/`, `./`, `../`, `~/`.
  root
  : Override the root used to compute relative labels and the header.
    Accepts a path literal, a `{ store, local }` pair, or anything accepted
    by `mkPaths`. Defaults to the module-level `paths`.
  label
  : Explicit label shown in the path header instead of the computed relative
    path. Also accepted as `name`.
  ```nix
  bat ./config.nix
  bat ./lib
  bat { path = ./src/main.nix; label = "main entry point"; }
  bat { path = ./src/util.nix; root = ./src; }
  bat {
    path = ./src/util.nix;
    root = { store = ./.; local = "/home/user/project"; };
  }
  ```
  */
  bat = input: let
    _name = "filesystem::bat";
    args =
      if isAttrs input
      then input
      else {path = input;};
    path = let
      candidate = args.path;
      isValidString =
        isString candidate
        && (
          false
          || hasPrefix "/" candidate
          || hasPrefix "./" candidate
          || hasPrefix "../" candidate
          || hasPrefix "~/" candidate
        );
    in
      if isPath candidate || isValidString
      then candidate
      else
        throw "${_name}: expected `path` to be a path or path-like string, got ${
          typeOf candidate
        }: ${toString candidate}";
    root = let
      candidate = args.root or null;
    in
      if candidate == null
      then mkPaths {inherit paths;}
      else if isAttrs candidate && (candidate ? store || candidate ? local)
      then
        mkPaths {
          store = candidate.store or candidate.local;
          local = candidate.local or toString candidate.store;
        }
      else mkPaths {store = candidate;};
    label = args.label or (args.name or null);
    toRelativePath = activeRoot: targetPath: let
      targetStr = toString targetPath;
      baseStr =
        if hasPrefix activeRoot.store.src targetStr
        then activeRoot.store.src
        else activeRoot.local.src;
    in
      if targetStr == baseStr
      then "."
      else if hasPrefix baseStr targetStr
      then "./" + substring (stringLength baseStr + 1) (-1) targetStr
      else "./" + targetStr;
    mkHeader = shownPath:
      concatStringsSep "\n" (
        ["#************************************************"]
        ++ (
          if root.store.src != root.local.src
          then [
            "#> STORE: ${root.store.src}"
            "#> LOCAL: ${root.local.src}"
          ]
          else ["#>  ROOT: ${root.local.src}"]
        )
        ++ ["#> STEMS: ${quote (toPathList shownPath)}"]
        ++ ["#************************************************"]
      );
    fileBlock = shown: child:
      mkHeader shown + "\n" + readFile child;
    collectFiles = displayRoot: dir: let
      entries = readDir dir;
      names = sort lessThan (attrNames entries);
    in
      concatLists (map (
          name: let
            child = dir + "/${name}";
            shown =
              if displayRoot != null
              then toRelativePath displayRoot child
              else toRelativePath root child;
          in
            if entries.${name} == "regular"
            then [(fileBlock shown child)]
            else if entries.${name} == "directory"
            then collectFiles displayRoot child
            else []
        )
        names);
    shownPath =
      if label != null
      then label
      else if isString path
      then path
      else toRelativePath root path;
    displayRoot =
      if readFileType path == "directory"
      then root
      else null;
  in
    if readFileType path == "directory"
    then concatStringsSep "\n\n" (collectFiles displayRoot path)
    else fileBlock shownPath path;
in
  exports

{
  attrsets,
  defaults,
  excludes,
  filesystem,
  lists,
  options,
  paths,
  strings,
  types,
  ...
}: let
  exports = {
    scoped = {
      module = importModule;
      all = importAll;
      collect = collectSpecs;
      collectNamed = collectNamedSpecs;
      importAttrs = readDirAttrs;
      resolve = resolveEntrypoint;
    };
    global = {
      inherit
        collectNamedSpecs
        collectSpecs
        importAll
        importModule
        readDirAttrs
        resolveEntrypoint
        ;
    };
  };
  inherit
    (attrsets)
    attrNames
    filterAttrs
    genAttrs
    mapAttrs
    mapAttrs'
    ;
  inherit (filesystem) pathExists readDir entrypoint entrypoints;
  inherit (lists) asModuleList any concatMap elem findFirst optionals;
  inherit (strings) hasSuffix removeSuffix;
  inherit (types) isFunction;
  candidates = entrypoints.nix.candidates or ["default.nix"];
  globalExcludes =
    excludes.paths
    or paths.excludes
    or defaults.excludes.paths
    or [
      "_"
      "archive"
      "backup"
      "bootstrap"
      "review"
      "temp"
      "default"
      "default.nix"
      "flake.nix"
    ];
  resolveExcludes = local:
    globalExcludes
    ++ (
      if local == null
      then []
      else if types.isAttrs local
      then local.paths or []
      else local
    );
  readDirAttrs = {
    base,
    excludes ? null,
    includes ? [],
    predicate ? null,
    includeFiles ? false,
  }: let
    excluded = map normalize (resolveExcludes excludes);
    normalize = name: removeSuffix ".nix" name;
    included = map normalize includes;
    isExcluded = name:
      elem (normalize name) excluded;
    isIncluded = name:
      elem (normalize name) included;
    isDefault = name:
      normalize name == "default";
    defaultPredicate = name: type:
      (type == "directory")
      || (
        includeFiles
        && type == "regular"
        && hasSuffix ".nix" name
        && !isDefault name
      );
    hasEntrypoint = name: type:
      if type == "directory"
      then any (f: pathExists (base + "/${name}/${f}")) candidates
      else true;
  in
    filterAttrs
    (
      name: type:
        (
          if predicate != null
          then predicate name type
          else defaultPredicate name type
        )
        && (!isExcluded name || isIncluded name)
        && hasEntrypoint name type
    )
    (readDir base);
  resolveEntrypoint = {
    base,
    name,
  }:
    findFirst
    (f: pathExists (base + "/${name}/${f}"))
    entrypoint
    candidates;
  hasEntrypointDir = base: name:
    any (f: pathExists (base + "/${name}/${f}")) candidates;
  importModule = {
    args ? {},
    base,
    name,
    path ? null,
  }: let
    isDir = (readDir base).${name} == "directory";
    resolved =
      if isDir
      then
        base
        + "/${name}/${
          if path != null
          then path
          else resolveEntrypoint {inherit base name;}
        }"
      else base + "/${name}";
    imported = import resolved;
  in
    if isFunction imported
    then imported args
    else imported;
  collectSpecs = {
    args,
    extraArgs ? {},
    base,
    excludes ? null,
    includes ? [],
    tags ? defaults.tags,
    includeFiles ? false,
    recurse ? false,
    rawTag ? "core",
    path ? [],
  }: let
    stem = name:
      if hasSuffix ".nix" name
      then removeSuffix ".nix" name
      else name;
    wrap = module:
      if module ? core || module ? home
      then module
      else {${rawTag} = module;};
    collect = ctxPath: base: let
      entries = readDirAttrs {inherit base excludes includes includeFiles;};
    in
      concatMap (
        name: let
          type = entries.${name};
          name' = stem name;
          path' = ctxPath ++ [name'];
          module = importModule {
            inherit base name;
            args =
              (removeAttrs args ["excludes" "includes"])
              // {
                path = path';
                leaf = name';
              }
              // extraArgs;
          };
          children =
            optionals
            (type == "directory" && !(hasEntrypointDir base name) && recurse)
            (collect path' (base + "/${name}"));
        in
          [(wrap module)] ++ children
      ) (attrNames entries);
    specs = collect path base;
  in
    genAttrs tags (
      tag:
        concatMap
        (spec: asModuleList (spec.${tag} or null))
        specs
    );
  collectNamedSpecs = {
    args ? {},
    extraArgs ? {},
    base,
    excludes ? null,
    includes ? [],
    tags ? defaults.tags,
    includeFiles ? false,
    rekey ? false,
    path ? [],
  }: let
    entries = readDirAttrs {inherit base excludes includes includeFiles;};
    raw =
      mapAttrs
      (
        name: type: let
          mod =
            if type == "regular"
            then removeSuffix ".nix" name
            else name;
          path' = path ++ [mod];
          importedModule = importModule {
            inherit base name;
            args =
              args
              // {
                inherit tags;
                path = path';
                leaf = mod;
              }
              // extraArgs;
          };
        in
          importedModule
          // {tags = (importedModule.tags or []) ++ asModuleList tags;}
      )
      entries;
  in
    if rekey
    then
      mapAttrs' (
        name: spec: let
          mod =
            if hasSuffix ".nix" name
            then removeSuffix ".nix" name
            else name;
        in {
          name = spec.name or mod;
          value = spec // {name = spec.name or mod;};
        }
      )
      raw
    else raw;
  importAll = args @ {
    base,
    excludes ? null,
    includes ? [],
    tags ? defaults.tags,
    extraArgs ? {},
    recurse ? false,
    includeFiles ? false,
    path ? [],
    ...
  }: let
    specs =
      collectSpecs
      {inherit args base excludes includes tags extraArgs includeFiles recurse path;};
  in {
    imports = specs.core or [];
    home-manager.sharedModules = specs.home or [];
  };
in
  exports

{
  attrsets,
  lists,
  debug,
  types,
  ...
