  : The value to test.
  ```nix
  isEmpty null
  isEmpty ""
  isEmpty "  "
  isEmpty []
  isEmpty {}
  isEmpty 0
  isEmpty false
  isEmpty "hello"
  isEmpty [1 2 3]
  ```
  */
  isEmpty = value:
    assert withContext {
      name = "isEmpty";
      assertion = !isFunction' value;
      message = "functions are not supported";
      context = "evaluating isEmpty";
    };
      if value == null
      then true
      else if isString value
      then value == "" || stringLength (trim value) == 0
      else if isList value
      then value == []
      else if isAttrs value
      then value == {}
      else false;
  /**
  Check if a value is not empty. Convenience negation of `isEmpty`.
  ```nix
  isNotEmpty :: a -> Bool
  ```
  - types.isEmpty
  value
  : The value to test.
  ```nix
  isNotEmpty "hello"
  isNotEmpty 0
  isNotEmpty false
  isNotEmpty null
  isNotEmpty ""
  isNotEmpty []
  validItems = filter isNotEmpty rawList;
  ```
  */
  isNotEmpty = value: !isEmpty value;
  /**
  Convert a value to a float.
  Accepts `int`, numeric `str`, or `float`. Strings are parsed via
  `fromJSON` and validated before coercion. Non-numeric strings
  throw a descriptive error.
  ```nix
  toFloat :: int | str | float -> float
  ```
  ```nix
  types.isFloat
  types.isInt
  types.isString
  strings.fromJSON
  ```
  value
  : The value to convert.
  #Examples
  > toFloat 1
  => 1.0
  > toFloat "3.14"
  => 3.14
  > toFloat 2.5
  => 2.5
  > toFloat "not a number"
  => error: toFloat: cannot convert string 'not a number' to a number
  */
  toFloat = value: let
    _name = "types::toFloat";
    _args = {
      inherit value;
      type = typeOf value;
    };
  in
    if isFloat value
    then value
    else if isInt value
    then value * 1.0
    else if isString value
    then let
      parsed = fromJSON value;
    in
      if isFloat parsed || isInt parsed
      then parsed * 1.0
      else throw "${_name}: Cannot convert string '${_args.value}' to a number"
    else throw "${_name}: Unsupported type: ${_args.type}";
  /**
  Option type that coerces values to float.
  For use in lib.mkOption { type = ...; }. Accepts the same inputs as
  toFloat but is a coercedTo type definition rather than a callable
  function.
  ```nix
  asFloat :: option-type
  ```
  ```nix
  types.coercedTo
  types.int
  types.str
  types.float
  strings.fromJSON
  types.isFloat
  types.isInt
  ```
  ```nix
  lib.mkOption {
    type = asFloat;
    default = 0.5;
  }
  > threshold = 0.5;
  > threshold = 1;
  > threshold = "2.5";
  */
  asFloat = let
    _name = "types::asFloat";
    fromInt = value: value * 1.0;
    fromStr = value: let
      parsed = fromJSON value;
    in
      if isFloat parsed || isInt parsed
      then parsed * 1.0
      else throw "${_name}: cannot convert string '${value}' to a number";
  in
    coercedTo int fromInt (coercedTo str fromStr float);
in
  exports

{
  defaults ? {},
  flake ? {},
  names ? {},
  excludes ? {},
  paths ? {},
}: let
  shared = let
    base =
      paths.store.libraries.shared or
      (paths.libraries.shared or
        (paths.shared or ./base));
    inherit (import base) recursiveUpdate;
    seed = {
      flake =
        recursiveUpdate {
          name = seed.names.src or seed.defaults.names.src;
          path = seed.paths.store.src or paths.src or ../.;
        }
        flake;
      defaults = recursiveUpdate {
        tags = ["core" "home"];
        labels = {
          browser = "Browser launch";
          editor = "Editor launch";
          visual = "Visual/IDE launch";
          launcher = "Launcher trigger";
          terminal = "Terminal launch";
        };
      } (recursiveUpdate defaults (flake.defaults or {}));
      excludes =
        recursiveUpdate {
          paths =
            [
              "_"
              "_.nix"
              "archive"
              "backup"
              "bootstrap"
              "review"
              "temp"
              "default"
              "default.nix"
              "flake.nix"
            ]
            ++ (paths.excludes or [])
            ++ (seed.defaults.excludes.paths or []);
        } (
          recursiveUpdate
          excludes
          (flake.excludes or (flake.defaults.excludes or {}))
        );
      paths = recursiveUpdate {
        excludes = seed.excludes.paths;
        store = {
          src = ../.;
          data = ../data;
          api = ../data;
          configuration = ../configuration;
        };
        local.src = "/etc/nixos";
      } (recursiveUpdate paths flake.paths or {});
      names = recursiveUpdate {
        src = "dots";
        lib = "lix";
      } (recursiveUpdate names (flake.names or {}));
    };
    assembly = import (base + "/assembly.nix") seed;
    inherit (assembly.global) mkLibrary;
  in
    mkLibrary {inherit base seed;};
  inherit (shared.charged) mkLibrary recursiveUpdate;
  global = let
    base =
      paths.store.libraries.global or (
        paths.libraries.global or (
          paths.global or ./imports
        )
      );
    built = mkLibrary {
      inherit base;
      seed =
        shared.charged
        // {bootstrap = import base shared.charged;}
        // {staged = shared;};
    };
    stripped = let
      lib = built.domains.libraries.default;
      charged =
        (
          recursiveUpdate
          (removeAttrs built.charged ["bootstrap"])
          built.domains.libraries.default
        )
        // {inherit lib;};
    in
      built
      // {
        inherit charged lib;
        ${names.lib or "lix"} = charged;
      };
    updated = recursiveUpdate stripped (let
      flakeArgs =
        built.domains
        // (with built.domains; {
          enable = libraries.default.types.isFlakeLike inputs;
          nixpkgs = inputs.normalized.nixpkgs or {};
        });
      flakeLibs = recursiveUpdate flakeArgs built.aliases;
    in {
      charged.flake =
        recursiveUpdate
        (stripped.charged.flake or {})
        flakeArgs;
      charged.flakes =
        recursiveUpdate
        (stripped.charged.flakes or {})
        flakeLibs;
      domains.libraries.merged.flakes =
        recursiveUpdate
        (stripped.lib.flakes or {})
        flakeLibs;
      domains.libraries.default.flakes =
        recursiveUpdate
        (stripped.charged.flakes or {})
        flakeLibs;
    });
  in
    updated;
  custom = let
    base = mkLibrary {
      base = ./custom;
      seed = global.charged // {staged = global;};
    };
    charged = base.charged // {pathsResolved = base.charged.mkPaths {};};
    updated =
      base
      // {
        inherit charged;
        ${names.lib or "lix"} = charged;
      };
  in
    updated;
  api = let
    base = ./api;
    seed =
      custom.charged
      // {
        custom = custom.domains // custom.aliases;
        api = import base (seed // {args = seed;});
      };
  in
    mkLibrary {
      inherit base seed;
    };
  config = let
    base = ./config;
    seed = api.charged // {api = api.domains // api.aliases;};
  in
    mkLibrary {inherit base seed;};
  merged = config.charged;
in {
  inherit api config custom shared merged global;
  inherit (merged) lib;
  ${names.lib or "lix"} = merged;
}

{
  attrsets ? {},
  lists ? {},
  defaults ? {},
  flake ? {},
  names ? {},
  types ? {},
  ...
}: let
  exports =
    {
      inputs = {inherit raw classified normalized;};
      types = predicates;
    }
    // predicates;
  predicates = {
    inherit
      collectModules
      getPackages
      hasLibraries
      hasFlakeModules
      hasCoreModules
      hasHomeModules
      hasOverlays
      isFlakeLike
      isHomeManagerLike
      isNixDarwinLike
      isNixpkgsInfrastructure
      isNixpkgsLike
      isTreefmtLike
      ;
  };
  inputs = flake.inputs or {};
  registry = flake.registry or {};
  isRegistryEntry = entry:
    isAttrs entry
    && entry ? source;
  registryEntries =
    registry.inputs or (filterAttrs (_: isRegistryEntry) registry);
  unwrapRegistryEntry = name: entry: let
    source = entry.source or entry.value or null;
    meta = removeAttrs entry ["source" "modules" "overlays" "libraries" "value"];
  in
    if isAttrs source
    then source // meta // {inherit name;}
    else entry;
  registryInputs =
    flake.imports or (mapAttrs unwrapRegistryEntry registryEntries);
  inherit (attrsets) attrNames getAttr hasAttr listToAttrs isAttrs maps mapAttrs orEmpty attrValues;
  inherit (lists) concatLists elem filter head length unique;
  inherit (types) concatStringsSep isString;
  filterAttrs =
    attrsets.filterAttrs or (predicate: set:
      listToAttrs (
        map
        (name: {
          inherit name;
          value = set.${name};
        })
        (
          filter
          (name: predicate name set.${name})
          (attrNames set)
        )
      ));
  recursiveUpdate =
    attrsets.recursiveUpdate or (
      lhs: rhs:
        if isAttrs lhs && isAttrs rhs
        then
          listToAttrs (map
            (name: {
              inherit name;
              value =
                if lhs ? ${name} && rhs ? ${name}
                then recursiveUpdate lhs.${name} rhs.${name}
                else rhs.${name} or lhs.${name};
            })
            (unique (attrNames lhs ++ attrNames rhs)))
        else rhs
    );
  firstOf =
    attrsets.firstOf or (
      set:
        if set == {}
        then null
        else head (attrValues set)
    );
  unwrapRegistryInput = entry:
    if isAttrs entry && entry ? value
    then let
      inherit (entry) value;
      meta = removeAttrs entry ["value"];
    in
      if isAttrs value
      then value // meta
      else entry
    else entry;
  #
  #
  pickModules = type: name: set: let
    values = attrValues set;
  in
    if set ? default
    then [set.default]
    else if length values == 1
    then values
    else
      throw ''
        flakes.collectModules: ${name}.${type} exposes multiple module keys with no 'default'.
        Available keys: ${concatStringsSep ", " (attrNames set)}
        Fix: add a 'default' key to the input's module set, or declare explicit
        module keys in the flake.nix inputs' registry entry for '${name}'.
      '';
  raw =
    filterAttrs
    (input: _: !(elem input ["self" (flake.name or names.src)]))
    inputs;
  collectModules = type: inputs: let
    attr =
      if type == "nixos"
      then "nixosModules"
      else if type == "darwin"
      then "darwinModules"
      else if type == "home"
      then "homeModules"
      else throw "flakes.collectModules:= unsupported type '${type}'";
    legacy =
      if type == "home"
      then "homeManagerModules"
      else null;
    get = name: input:
      if hasAttr attr input
      then pickModules type name (getAttr attr input)
      else if legacy != null && hasAttr legacy input
      then pickModules type name (getAttr legacy input)
      else [];
  in
    concatLists (attrValues (maps get inputs));
  flattenRegistryModules = modules:
    concatLists (
      map
      (value:
        if isAttrs value
        then concatLists (attrValues value)
        else value)
      (attrValues modules)
    );
  hasRegistryModules = entry:
    flattenRegistryModules (entry.modules or {}) != [];
  autoClassified = {
    nixpkgs = filterAttrs (_: isNixpkgsLike) raw;
    nix-darwin = filterAttrs (_: isNixDarwinLike) raw;
    treefmt = filterAttrs (_: isTreefmtLike) raw;
    colmena = filterAttrs (input: _: input == "deployColmena") raw;
    nixos-anywhere = filterAttrs (input: _: input == "deployAnywhere") raw;
    home-manager =
      filterAttrs
      (
        _input: isHomeManagerLike
      )
      raw;
    modules =
      filterAttrs
      (
        _input: value:
          hasFlakeModules value
          && !(isNixpkgsLike value)
          && !(isHomeManagerLike value)
          && !(isNixDarwinLike value)
          && !(isTreefmtLike value)
      )
      raw;
    overlays = filterAttrs (_: hasOverlays) raw;
    packages =
      filterAttrs
      (_: value: value ? packages && !(isNixpkgsLike value))
      raw;
    libraries = filterAttrs (_: hasLibraries) raw;
    infrastructure = filterAttrs (_: isNixpkgsInfrastructure) raw;
    deployment =
      filterAttrs
      (input: _: elem input ["deployColmena" "deployAnywhere"])
      raw;
  };
  registryClassified = {
    nixpkgs = filterAttrs (_: isNixpkgsLike) registryInputs;
    nix-darwin = filterAttrs (_: isNixDarwinLike) registryInputs;
    treefmt = filterAttrs (_: isTreefmtLike) registryInputs;
    colmena = filterAttrs (name: _: name == "colmena") registryInputs;
    nixos-anywhere = filterAttrs (name: _: name == "nixos-anywhere") registryInputs;
    home-manager = filterAttrs (_: isHomeManagerLike) registryInputs;
    modules = filterAttrs (name: _: hasRegistryModules (registryEntries.${name} or {})) registryInputs;
    overlays = filterAttrs (name: _: (registryEntries.${name}.overlays or {}) != {}) registryInputs;
    packages = filterAttrs (_: value: getPackages value != {}) registryInputs;
    libraries = filterAttrs (_: hasLibraries) registryInputs;
    infrastructure = filterAttrs (name: _: elem "infrastructure" (registryEntries.${name}.profiles or [])) registryInputs;
    deployment = filterAttrs (name: _: elem "deployment" (registryEntries.${name}.profiles or [])) registryInputs;
  };
  classified =
    if registryInputs != {}
    then registryClassified
    else autoClassified;
  autoNormalized = recursiveUpdate classified {
    inherit raw;
    nixpkgs =
      if flake ? nixpkgs
      then
        if isString (flake.nixpkgs or {})
        then let name = flake.nixpkgs; in inputs.${name} // {inherit name;}
        else flake.nixpkgs
      else if defaults ? nixpkgs
      then
        if isString defaults.nixpkgs
        then let name = defaults.nixpkgs; in inputs.${name} // {inherit name;}
        else defaults.nixpkgs
      else firstOf classified.nixpkgs;
    nix-darwin = firstOf classified.nix-darwin;
    home-manager = firstOf classified.home-manager;
    treefmt = firstOf classified.treefmt;
    colmena = firstOf classified.colmena;
    nixos-anywhere = firstOf classified."nixos-anywhere";
    deployment = {
      colmena = firstOf classified.colmena;
      nixos-anywhere = firstOf classified."nixos-anywhere";
    };
  };
  normalized = autoNormalized // (mapAttrs (_: unwrapRegistryInput) registryInputs);
  getPackages = input: let
    value = orEmpty input;
  in
    orEmpty (value.legacyPackages or {})
    // orEmpty (value.packages or {});
  hasLibraries = input:
    input ? lib;
  hasFlakeModules = input:
    hasCoreModules input || hasHomeModules input;
  hasCoreModules = input:
    input ? nixosModules || input ? darwinModules;
  hasHomeModules = input:
    input ? homeModules || input ? homeManagerModules;
  hasOverlays = input:
    input ? overlays;
  isFlakeLike = inputs:
    ((inputs.classified.modules or {}) != {})
    || ((inputs.classified.overlays or {}) != {})
    || ((inputs.normalized.nixpkgs or {}) != {});
  isNixpkgsLike = input:
    input ? legacyPackages
    && input ? lib
    && !(input ? __functor);
  isNixDarwinLike = input:
    input ? darwinModules
    && input ? lib
    && !(input ? legacyPackages)
    && !(input ? nixosModules)
    && !(input ? homeModules)
    && !(input ? homeManagerModules);
  isHomeManagerLike = input:
    input ? nixosModules
    && input ? darwinModules
    && input ? legacyPackages
    && input ? lib
    && input ? flakeModules
    && !(input ? homeModules);
  isTreefmtLike = input:
    input ? lib
    && input.lib ? evalModule
    && input ? flakeModule
    && !(input ? legacyPackages)
    && !(hasFlakeModules input)
    && !(hasOverlays input);
  isNixpkgsInfrastructure = input:
    isNixpkgsLike input
    && !(hasFlakeModules input)
    && !(hasOverlays input);
in
  exports

{bootstrap, ...}: let
  exports = {
    scoped =
      {
        inherit (inputs) raw classified normalized;
        enable = types.isFlakeLike inputs;
      }
      // types;
    global = types;
  };
  inherit (bootstrap) inputs;
  types = {inherit (bootstrap) isFlakeLike isHomeManagerLike isNixDarwinLike isNixpkgsInfrastructure isNixpkgsLike isTreefmtLike;};
in
  exports

