}: let
  exports = {
    scoped = {
      inherit classified normalized excluded getPackages;
      merged = classified // normalized;
      default = orEmpty normalized.nixpkgs;
    };
    global = {getFlakePackages = getPackages;};
  };
  excluded = excludes.packages or [];
